import React, { useState, useContext } from 'react';
import { Container, Row, Col, Form, FormGroup, Button, Input } from 'reactstrap';
import { AuthContext } from '../../context/AuthContext';
import { BASE_URL } from '../../utils/config';

const Profile = () => {
   const { user } = useContext(AuthContext); // Lấy thông tin user đang đăng nhập
   const [passwords, setPasswords] = useState({ oldPassword: '', newPassword: '' });

   const handlePasswordChange = async (e) => {
      e.preventDefault();
      const token = localStorage.getItem('token');

      try {
         const res = await fetch(`${BASE_URL}/users/update-password`, {
            method: 'POST',
            headers: {
               'Content-Type': 'application/json',
               'Authorization': `Bearer ${token}`
            },
            body: JSON.stringify(passwords)
         });

         const result = await res.json();
         alert(result.message);
         if (res.ok) setPasswords({ oldPassword: '', newPassword: '' });
      } catch (err) {
         alert("Lỗi kết nối!");
      }
   };

   return (
      <Container className="mt-5">
         <Row>
            <Col lg='4'>
               <div className="profile__info p-4 shadow-sm rounded bg-white">
                  <h4>Thông tin cá nhân</h4>
                  <p><strong>Tên:</strong> {user?.username}</p>
                  <p><strong>Email:</strong> {user?.email}</p>
                  <p><strong>Vai trò:</strong> {user?.role}</p>
               </div>
            </Col>

            <Col lg='8'>
               <div className="password__change p-4 shadow-sm rounded bg-white">
                  <h4>Đổi mật khẩu</h4>
                  <Form onSubmit={handlePasswordChange}>
                     <FormGroup>
                        <Input type="password" placeholder="Mật khẩu cũ" required 
                           onChange={e => setPasswords({...passwords, oldPassword: e.target.value})} />
                     </FormGroup>
                     <FormGroup>
                        <Input type="password" placeholder="Mật khẩu mới" required 
                           onChange={e => setPasswords({...passwords, newPassword: e.target.value})} />
                     </FormGroup>
                     <Button type="submit" color="primary">Cập nhật mật khẩu</Button>
                  </Form>
               </div>
            </Col>
         </Row>
      </Container>
   );
};

export default Profile;
